export function LegalContent({ lang: langProp, heading = "h1" }: { lang?: Lang; heading?: "h1" | "h2" } = {}) {
  const { lang: globalLang } = useLang();
  const lang = langProp ?? globalLang;
  const t = getDict(lang);
  const doc = lang === "en" ? EN : RU;
  // На странице /privacy это единственный заголовок страницы → h1.
  // В модалке (её открывают из подвала ЛЮБОЙ страницы) h1 уже занят
  // заголовком самой страницы, поэтому там передаём h2 — иначе на странице
  // оказывается два h1. Классы те же, вид не меняется.
  const Heading = heading;
  return (
    <div className="space-y-5 text-sm leading-relaxed text-[#e0860c]">
      <div>
        <Heading className="text-xl font-bold text-[#e0860c]">{t.legal.privacyAndTerms}</Heading>
        <p className="mt-1 text-xs text-[#e0860c]">{t.legal.lastUpdated}</p>
      </div>
      <p className="rounded-xl bg-orange-50/70 p-3 text-[#e0860c]">{doc.intro}</p>
      {doc.sections.map((s) => (
        <section key={s.h}>
          <h2 className="mb-1.5 font-bold text-[#e0860c]">{s.h}</h2>
          <div className="space-y-1.5">
            {s.p.map((para, i) => (
              <p key={i}>{para}</p>
            ))}
          </div>
        </section>
      ))}
    </div>
  );
}
